def quorum_write(replicas, value, version, W):
    acks = 0
    for r in replicas:
        try:
            r.store(value, version, timeout_ms=50)
            acks += 1
        except Timeout:
            continue  # straggler becomes repair debt, not failure
    return acks >= W  # success means overlap for future R where R + W > N

def quorum_read(replicas, R):
    responses = []
    for r in replicas:
        try:
            responses.append(r.fetch(timeout_ms=50))
            if len(responses) >= R:
                break
        except Timeout:
            continue
    if len(responses) < R:
        raise Unavailable("cannot meet R")
    newest = max(responses, key=lambda x: x.version)
    # read-repair: push newest back async, else staleness never converges
    for r, resp in zip(replicas, responses):
        if resp.version < newest.version:
            r.repair_async(newest)
    return newest.value

